import{_ as a}from"./chunks/pdf-import-triage.VhDzuCgc.js";import{_ as t,o as n,c as o,a2 as s}from"./chunks/framework.D_TdfPur.js";const m=JSON.parse(`{"title":"What's new","description":"What changed in michi-chat, release by release, in plain words for business owners.","frontmatter":{"description":"What changed in michi-chat, release by release, in plain words for business owners.","head":[["link",{"rel":"canonical","href":"https://beany-vu.github.io/michi-chat/whats-new"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:site_name","content":"michi-chat"}],["meta",{"property":"og:title","content":"What's new"}],["meta",{"property":"og:description","content":"What changed in michi-chat, release by release, in plain words for business owners."}],["meta",{"property":"og:url","content":"https://beany-vu.github.io/michi-chat/whats-new"}],["meta",{"property":"og:image","content":"https://beany-vu.github.io/michi-chat/og-card.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:image:alt","content":"michi-chat: a chat assistant platform for small businesses, with the Michi cat crest"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"What's new"}],["meta",{"name":"twitter:description","content":"What changed in michi-chat, release by release, in plain words for business owners."}],["meta",{"name":"twitter:image","content":"https://beany-vu.github.io/michi-chat/og-card.png"}]]},"headers":[],"relativePath":"whats-new.md","filePath":"whats-new.md"}`),r={name:"whats-new.md"};function i(h,e,l,d,c,p){return n(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="what-s-new" tabindex="-1">What&#39;s new <a class="header-anchor" href="#what-s-new" aria-label="Permalink to &quot;What&#39;s new&quot;">​</a></h1><p>The headline changes, newest first. The full list lives in <a href="https://github.com/beany-vu/michi-chat/blob/master/CHANGELOG.md" target="_blank" rel="noreferrer">CHANGELOG.md</a>.</p><h2 id="v0-2-32-no-more-empty-handed-answers" tabindex="-1">v0.2.32 - no more empty-handed answers <a class="header-anchor" href="#v0-2-32-no-more-empty-handed-answers" aria-label="Permalink to &quot;v0.2.32 - no more empty-handed answers&quot;">​</a></h2><p>When the assistant said &quot;let me check&quot; and then went quiet, or searched and searched and ended with &quot;Sorry, I could not answer that one&quot;, it was the loop giving up, not the knowledge. Both now get a second chance: an announced lookup is nudged to actually happen, and a search that runs out of rounds is turned into an answer from what it found. The persona also has more room, six thousand characters, for the rules that keep a conversation on track.</p><h2 id="v0-2-31-no-more-next-event-that-already-happened" tabindex="-1">v0.2.31 - no more &quot;next event&quot; that already happened <a class="header-anchor" href="#v0-2-31-no-more-next-event-that-already-happened" aria-label="Permalink to &quot;v0.2.31 - no more &quot;next event&quot; that already happened&quot;">​</a></h2><p>If the assistant was asked what is coming up and named an event from last month, that is fixed: the events lookup now tells the assistant plainly which events are upcoming, which are still running, and which are over, and says &quot;nothing is scheduled right now&quot; when that is the truth. Also fixed: the michi shield in the admin was missing on production.</p><h2 id="v0-2-30-you-can-watch-an-import-happen" tabindex="-1">v0.2.30 - you can watch an import happen <a class="header-anchor" href="#v0-2-30-you-can-watch-an-import-happen" aria-label="Permalink to &quot;v0.2.30 - you can watch an import happen&quot;">​</a></h2><p>Importing a tenant used to mean staring at a spinning button and, for a big knowledge base, an error page when the connection gave up. Now the import starts and the page answers right away; the tenant page and the knowledge page show a banner that counts up, &quot;7 of 9 documents, 3,120 of 7,003 chunks, embedding HS 2022 product codes&quot;, and ends with &quot;Imported 9 documents in 70s&quot; or the reason it failed. Documents that did not change are skipped. If someone starts a second import of the same tenant while one is running, they get a polite no with the current progress.</p><h2 id="v0-2-29-big-imports-and-wide-logos" tabindex="-1">v0.2.29 - big imports and wide logos <a class="header-anchor" href="#v0-2-29-big-imports-and-wide-logos" aria-label="Permalink to &quot;v0.2.29 - big imports and wide logos&quot;">​</a></h2><p>Two things stopped saying &quot;This page couldn&#39;t load&quot;: importing a large tenant file and saving a very large knowledge document. Both used to hit a hidden 1 MB limit; it is now 8 MB. And a tenant whose logo is a wide wordmark, not a square mark, now sees it whole in the chat header instead of cropped. In the tenant list, coach tenants carry a small badge.</p><h2 id="v0-2-28-staff-see-only-their-tenants" tabindex="-1">v0.2.28 - staff see only their tenants <a class="header-anchor" href="#v0-2-28-staff-see-only-their-tenants" aria-label="Permalink to &quot;v0.2.28 - staff see only their tenants&quot;">​</a></h2><p>On Accounts you now tick which tenants a staff account may see, and that is all they see anywhere in the admin: tenant list, conversations, Unanswered, Usage, analytics, knowledge base. A staff account with nothing ticked sees nothing until you assign it, so a new login is safe by default. Owners keep seeing everything. If you already have staff accounts, tick their tenants after this update, or they will find an empty admin. Unanswered also got the tenant chips from Conversations.</p><h2 id="v0-2-27-the-page-head-stays-with-you-everywhere" tabindex="-1">v0.2.27 - the page head stays with you everywhere <a class="header-anchor" href="#v0-2-27-the-page-head-stays-with-you-everywhere" aria-label="Permalink to &quot;v0.2.27 - the page head stays with you everywhere&quot;">​</a></h2><p>The sticky head from the tenant form now applies to every admin page that has something to press up there: a transcript&#39;s Flag, Export, Delete and Back, the knowledge base and analytics links, the tenant filters on Conversations. Scroll as far as you like; the way back is always at the top.</p><h2 id="v0-2-26-links-you-can-tap-and-a-glossary-for-the-bars" tabindex="-1">v0.2.26 - links you can tap, and a glossary for the bars <a class="header-anchor" href="#v0-2-26-links-you-can-tap-and-a-glossary-for-the-bars" aria-label="Permalink to &quot;v0.2.26 - links you can tap, and a glossary for the bars&quot;">​</a></h2><p>When the assistant gives an email, a phone number or a web address, it is now a real link: tap to mail, tap to call, tap to open the page in a new tab. On the Analytics page the &quot;What visitors reach for&quot; bars used to show bare function names; each one now comes with a plain-words card saying what it does, what goes in and what comes back. The tenant form keeps its name, links and Save button in view while you scroll. And when the cafe website cannot report the weather, the assistant suggests a drink from the specials or the menu instead of apologising.</p><h2 id="v0-2-25-a-second-kind-of-tenant-the-coach" tabindex="-1">v0.2.25 - a second kind of tenant: the coach <a class="header-anchor" href="#v0-2-25-a-second-kind-of-tenant-the-coach" aria-label="Permalink to &quot;v0.2.25 - a second kind of tenant: the coach&quot;">​</a></h2><p>Until now every tenant was a customer assistant for one business. There is now a second kind, <strong>coach</strong>: an application sends it facts with every message and it explains them to one learner, without the &quot;I only answer questions about the business&quot; reflex. The first one is Chess Mate, where Stockfish judges each move and the coach explains why in plain words. Nothing changes for a normal install: the Kind field only appears when the instance enables it (see Extending), and everything else (persona, keys, transcripts, usage) works exactly as before.</p><h2 id="v0-2-22-no-more-feeling-lost-at-the-slack-field" tabindex="-1">v0.2.22 - no more feeling lost at the Slack field <a class="header-anchor" href="#v0-2-22-no-more-feeling-lost-at-the-slack-field" aria-label="Permalink to &quot;v0.2.22 - no more feeling lost at the Slack field&quot;">​</a></h2><p>The Slack webhook field now teaches you how to get a webhook, right on the form: four steps, two minutes, free. The same walkthrough (with channel tips) is in <a href="./owner/day-to-day#get-pinged-when-it-matters">Running it day to day</a>.</p><h2 id="v0-2-22-v0-2-23-guidance-and-the-cobalt-roofline" tabindex="-1">v0.2.22 &amp; v0.2.23 - guidance and the cobalt roofline <a class="header-anchor" href="#v0-2-22-v0-2-23-guidance-and-the-cobalt-roofline" aria-label="Permalink to &quot;v0.2.22 &amp; v0.2.23 - guidance and the cobalt roofline&quot;">​</a></h2><p>The Slack webhook field now teaches you how to get a webhook (four steps, right under the input). And the admin&#39;s look sharpened, on the owner&#39;s own brief - Danish architecture, calm walls with one precise roof detail: every panel wears a thin cobalt top edge, active items carry the same cobalt, corners are square everywhere, and a missing bottom border on the header chips (a real bug) is fixed, so the console reads crisp instead of faded.</p><h2 id="v0-2-21-the-owner-s-to-do-list-and-friends" tabindex="-1">v0.2.21 - the owner&#39;s to-do list, and friends <a class="header-anchor" href="#v0-2-21-the-owner-s-to-do-list-and-friends" aria-label="Permalink to &quot;v0.2.21 - the owner&#39;s to-do list, and friends&quot;">​</a></h2><ul><li><strong>Unanswered</strong> - a new page listing every question the bot admitted it couldn&#39;t answer, with an &quot;Add fact&quot; shortcut. It is the knowledge base&#39;s to-do list.</li><li><strong>Find the bad actors faster</strong>: a 🚩 Flagged chip and paging on Conversations.</li><li><strong>Answer cache, visible</strong>: see the instantly-served answers per tenant (hit counts show what visitors ask most), evict a stale one, or clear all.</li><li><strong>Retention</strong>: &quot;delete conversations after N days&quot;, per tenant, automatic.</li><li><strong>Failed turns show up</strong> in transcripts as a <code>failed</code> label instead of a silent gap.</li><li><strong>The mobile admin got a burger menu</strong> - the old horizontal strip was bursting.</li></ul><h2 id="v0-2-19-v0-2-20-design-polish" tabindex="-1">v0.2.19 &amp; v0.2.20 - design polish <a class="header-anchor" href="#v0-2-19-v0-2-20-design-polish" aria-label="Permalink to &quot;v0.2.19 &amp; v0.2.20 - design polish&quot;">​</a></h2><p>The &quot;Choose File&quot; chip on the PDF and CSV imports now matches the admin&#39;s own buttons, and each step of the PDF import shows exactly one primary button, so the next action is always obvious. Small AI tidy-ups also got headroom on providers that &quot;think&quot; out loud.</p><h2 id="v0-2-18-pdfs-into-the-knowledge-base" tabindex="-1">v0.2.18 - PDFs into the knowledge base <a class="header-anchor" href="#v0-2-18-pdfs-into-the-knowledge-base" aria-label="Permalink to &quot;v0.2.18 - PDFs into the knowledge base&quot;">​</a></h2><p>Upload a PDF on the knowledge-base page and the analysis is free: it reads the text out, strips page numbers and repeated headers at no cost, flags scanned files and table-heavy content, and shows what an AI tidy-up would cost <strong>before</strong> you run it. Delete what customers don&#39;t need, run the tidy-up (or skip it), review, save. The actual token usage is reported after, so the estimate earns its keep. Owners: the step-by-step tutorial is <a href="./owner/import-a-pdf">Turn a PDF into knowledge</a>; the reference lives in <a href="./guide/knowledge-base#import-from-a-pdf">Knowledge base → Import from a PDF</a>.</p><p><img src="'+a+'" alt="PDF import: free analysis with a token estimate"></p><h2 id="v0-2-17-a-cleaner-console" tabindex="-1">v0.2.17 - a cleaner console <a class="header-anchor" href="#v0-2-17-a-cleaner-console" aria-label="Permalink to &quot;v0.2.17 - a cleaner console&quot;">​</a></h2><p>The admin navigation got a redesign: normal-case labels with hairline icons and a clear active marker. The knowledge-base page now explains how to bring facts in from a PDF or Word file (copy the text, paste, tidy into short sections).</p><h2 id="v0-2-16-transcripts-that-teach" tabindex="-1">v0.2.16 - transcripts that teach <a class="header-anchor" href="#v0-2-16-transcripts-that-teach" aria-label="Permalink to &quot;v0.2.16 - transcripts that teach&quot;">​</a></h2><p>Every assistant turn in a transcript now carries a label for how the answer was produced, one of four cases: <strong>cached</strong>, <strong>guardrail</strong>, <strong>used tools</strong>, or <strong>model only</strong>. Hover the label and the tooltip explains the case, why the turn does or doesn&#39;t show tokens, and why the debug block is there or not.</p><h2 id="v0-2-15-flagging-the-baiters" tabindex="-1">v0.2.15 - flagging the baiters <a class="header-anchor" href="#v0-2-15-flagging-the-baiters" aria-label="Permalink to &quot;v0.2.15 - flagging the baiters&quot;">​</a></h2><p>Shaped by a weekend of people probing the live bot.</p><ul><li><strong>Flagged conversations.</strong> Prompt-injection bait and <code>/command</code> probes get a fixed refusal (no model runs), the turns are stored, and the conversation is auto-flagged 🚩 in the admin with the reason. You can also flag or unflag any conversation by hand.</li><li><strong>Shorter refusals.</strong> Off-topic questions get one polite sentence, not an essay, and requests for help with the admin portal, passwords, or account recovery are declined outright, whoever claims to be asking.</li><li><strong>Optional visitor analytics.</strong> Point <code>GA_MEASUREMENT_ID</code> at a GA4 property and the visitor chat pages report per tenant; the admin stays untracked.</li></ul><h2 id="v0-2-14-cache-visibility" tabindex="-1">v0.2.14 - cache visibility <a class="header-anchor" href="#v0-2-14-cache-visibility" aria-label="Permalink to &quot;v0.2.14 - cache visibility&quot;">​</a></h2><p>Transcript turns served from the answer cache are now badged &quot;cached&quot;.</p><h2 id="v0-2-13-readable-tool-debugging" tabindex="-1">v0.2.13 - readable tool debugging <a class="header-anchor" href="#v0-2-13-readable-tool-debugging" aria-label="Permalink to &quot;v0.2.13 - readable tool debugging&quot;">​</a></h2><p>The tool-calls expander in transcripts pretty-prints each call and its result.</p><h2 id="v0-2-12-readable-transcripts" tabindex="-1">v0.2.12 - readable transcripts <a class="header-anchor" href="#v0-2-12-readable-transcripts" aria-label="Permalink to &quot;v0.2.12 - readable transcripts&quot;">​</a></h2><p>Conversation transcripts are now a chat view (visitor right, assistant left), and every admin timestamp shows in your own timezone instead of the server&#39;s.</p><h2 id="v0-2-11-honest-thermometer" tabindex="-1">v0.2.11 - honest thermometer <a class="header-anchor" href="#v0-2-11-honest-thermometer" aria-label="Permalink to &quot;v0.2.11 - honest thermometer&quot;">​</a></h2><p>Weather answers now state the air temperature, and only call the heat index &quot;feels like&quot;.</p><h2 id="v0-2-10-right-events-phone-friendly" tabindex="-1">v0.2.10 - right events, phone-friendly <a class="header-anchor" href="#v0-2-10-right-events-phone-friendly" aria-label="Permalink to &quot;v0.2.10 - right events, phone-friendly&quot;">​</a></h2><p>&quot;What&#39;s coming up?&quot; now answers with events that are actually upcoming, judged in the cafe&#39;s own timezone. The admin works properly on phones, and the chat footer fits one line.</p><h2 id="v0-2-7-smoother-chat" tabindex="-1">v0.2.7 - smoother chat <a class="header-anchor" href="#v0-2-7-smoother-chat" aria-label="Permalink to &quot;v0.2.7 - smoother chat&quot;">​</a></h2><p>Messages and chips now animate in, and image builds are much faster.</p><h2 id="v0-2-6-faster-safer-more-accurate" tabindex="-1">v0.2.6 - faster, safer, more accurate <a class="header-anchor" href="#v0-2-6-faster-safer-more-accurate" aria-label="Permalink to &quot;v0.2.6 - faster, safer, more accurate&quot;">​</a></h2><p>Upgraded the framework to Next.js 16, which clears the outstanding security advisories. Faster tool answers (caching + parallel + shorter timeouts), no invented menu items or bean origins, and raw backend errors never shown to visitors.</p><h2 id="v0-2-2-safety-hardening" tabindex="-1">v0.2.2 - safety hardening <a class="header-anchor" href="#v0-2-2-safety-hardening" aria-label="Permalink to &quot;v0.2.2 - safety hardening&quot;">​</a></h2><p>Shaped by real questions people asked the live bot on launch day.</p><ul><li><strong>Protection rules per tenant.</strong> A plain-words box on the tenant form for hard boundaries (&quot;never quote rental prices&quot;, &quot;no stories&quot;). It can only tighten the bot, never loosen the platform rules. See <a href="./guide/admin">The admin UI</a>.</li><li><strong>Answers only from real data.</strong> The bot no longer names menu items from memory; if the live menu does not list something, it says so. No invented dishes.</li><li><strong>No off-topic writing.</strong> Stories, poems and role-play are declined.</li><li><strong>Stays private about itself.</strong> It won&#39;t discuss its tools, data sources, models or hosting, even to someone claiming to be the owner.</li><li><strong>Speaks the visitor&#39;s language.</strong> English, Filipino, Taglish, and more, matched automatically.</li><li><strong>Instant refusal of obvious attacks</strong>, with no model call, plus a multilingual model backstop for the rest.</li></ul><h2 id="v0-2-0-the-platform-grew-up" tabindex="-1">v0.2.0 - the platform grew up <a class="header-anchor" href="#v0-2-0-the-platform-grew-up" aria-label="Permalink to &quot;v0.2.0 - the platform grew up&quot;">​</a></h2><ul><li><strong>Roles and an audit trail.</strong> Owner and staff logins; every change is recorded. See <a href="./owner/day-to-day">Running it day to day</a>.</li><li><strong>Analytics per tenant.</strong> What visitors ask, which tools they reach for, busy hours, and where they come from.</li><li><strong>Move a whole tenant as one file.</strong> Export settings and knowledge, import elsewhere.</li><li><strong>Instant repeat answers.</strong> Common questions are cached and served at zero cost.</li><li><strong>Graded answer quality.</strong> A second model checks the bot&#39;s answers for faithfulness.</li><li><strong>Branding</strong>: your logo, accent colour, light/dark, and a visitor notice.</li></ul><h2 id="v0-1-0-first-release" tabindex="-1">v0.1.0 - first release <a class="header-anchor" href="#v0-1-0-first-release" aria-label="Permalink to &quot;v0.1.0 - first release&quot;">​</a></h2><p>The multi-tenant assistant: per-business persona, tools and knowledge base, an embeddable widget, and the operator admin.</p>',57)])])}const w=t(r,[["render",i]]);export{m as __pageData,w as default};
